467 : 
468 :         if (decPos > -1) {
469 : 
470 :             if (expPos > -1) {
471 :                 if (expPos < decPos || expPos > str.length()) {
472 :                     throw new NumberFormatException(str + " is not a valid number.");
473 :                 }
