491 :             if (expPos > -1 && expPos < str.length() - 1) {
492 :                 exp = str.substring(expPos + 1, str.length() - 1);
493 :             } else {
494 :                 exp = null;
495 :             }
496 :             //Requesting a specific type..
497 :             String numeric = str.substring(0, str.length() - 1);
