499 :             switch (lastChar) {
500 :                 case 'l' :
501 :                 case 'L' :
502 :                     if (dec == null
503 :                         && exp == null
504 :                         && (numeric.charAt(0) == '-' && isDigits(numeric.substring(1)) || isDigits(numeric))) {
505 :                         try {
506 :                             return createLong(numeric);
507 :                         } catch (NumberFormatException nfe) { // NOPMD
508 :                             // Too big for a long
509 :                         }
510 :                         return createBigInteger(numeric);
511 : 
512 :                     }
