584 :                         return d;
585 :                     }
586 :                 } catch (NumberFormatException nfe) { // NOPMD
587 :                     // ignore the bad number
588 :                 }
589 : 
590 :                 return createBigDecimal(str);
591 : 
592 :             }
593 :         }
