"604 :     private static boolean isAllZeros(String str) {
605 :         if (str == null) {
606 :             return true;
607 :         }
608 :         for (int i = str.length() - 1; i >= 0; i--) {
609 :             if (str.charAt(i) != '0') {
610 :                 return false;
611 :             }
612 :         }
613 :         return str.length() > 0;
614 :     }"

